import {freshJob,changeVehicle,attachSelection,selectedPartsList,createEpcLaunchGate} from './jobs.js';
import {analyzeVin} from './vin.js';
import {createVinEntry,readPendingVinResolution} from './vin-ui.js';
import {search} from './core.js';
export function createCounter(api){
 const {esc,panel,toast,copy,download,read,save}=api,$=s=>document.querySelector(s);
 let lookup=null;const nativeLaunch=createEpcLaunchGate();
 const saveJob=j=>api.writeJob(j);
 const savedVehicles=()=>[...read('vin-cache',[]),...api.getJobs().items];
 function openSnapOn(){
  if(!api.getIndex()){toast('The part reference is still loading.');return;}
  let selected=null,matched=[];const active=api.getJob();
  panel(`<div class="snapon-intro"><span class="dialog-category">SNAP-ON WORKSPACE</span><h2>One VIN.<br>The part you need.</h2><p>Your familiar parts search, connected to your catalog.</p><div class="snapon-route"><span>VIN</span><b>→</b><span>Part family</span><b>→</b><span>Service number</span></div></div><form id="snaponForm"><label class="note-label" for="snaponVin">Vehicle identification number</label><input class="snapon-input vin-entry" id="snaponVin" maxlength="30" value="${esc(active.vin)}" placeholder="Full VIN or last 8 characters" autocapitalize="characters" autocomplete="off" spellcheck="false"><div id="snaponVinChoices" aria-live="polite"></div><label class="note-label" for="snaponQuery">Part name, description or base number</label><input class="snapon-input" type="search" id="snaponQuery" maxlength="160" placeholder="Try purge valve, wheel hub or 1104…" autocomplete="off"><div class="snapon-suggestions"><button type="button" data-snap-query="purge valve">Purge valve</button><button type="button" data-snap-query="wheel hub">Wheel hub</button><button type="button" data-snap-query="brake pads">Brake pads</button></div><p id="snaponStatus" role="status">Search the same ${api.getIndex().byBase.size.toLocaleString()} base-number reference used throughout the app.</p><div id="snaponMatches" class="snapon-matches"></div><section id="snaponSelected" hidden></section><button id="snaponLaunch" class="primary wide" type="submit" disabled>Choose a part to continue</button><p class="micro">Online catalog access uses your Snap-on account. The phone requires its own sign-in. A different VIN opens a separate job so your current vehicle stays intact.</p></form>`);
  const vinEntry=createVinEntry({input:$('#snaponVin'),choices:$('#snaponVinChoices'),esc,getRecords:savedVehicles});
  function showMatches(){selected=null;$('#snaponSelected').hidden=true;$('#snaponLaunch').disabled=true;$('#snaponLaunch').textContent='Choose a part to continue';const q=$('#snaponQuery').value.trim();matched=q?search(q,api.getIndex()):[];$('#snaponStatus').textContent=q?`${matched.length} matching part ${matched.length===1?'family':'families'}. Choose one to see its base numbers.`:'Enter a common name or a base number to begin.';$('#snaponMatches').innerHTML=matched.slice(0,12).map(({part:p,reason},i)=>`<button type="button" class="snapon-match" data-snap-match="${i}"><span><strong>${esc(p.name)}</strong><small>${esc(p.category)} · ${p.broad?'Broad source group':esc(reason)}</small><code>${p.codes.slice(0,6).map(esc).join(' · ')}${p.codes.length>6?' +'+(p.codes.length-6)+' more':''}</code></span><b>↗</b></button>`).join('')+(matched.length>12?'<p class="micro">Showing the first 12 families. Add a more specific term to narrow the list.</p>':'');}
  $('#snaponQuery').oninput=showMatches;
  document.querySelectorAll('[data-snap-query]').forEach(b=>b.onclick=()=>{$('#snaponQuery').value=b.dataset.snapQuery;showMatches();});
  $('#snaponMatches').onclick=e=>{const b=e.target.closest('[data-snap-match]');if(!b)return;const hit=matched[+b.dataset.snapMatch];if(!hit)return;selected=hit.part;const ordered=[...hit.matched,...selected.codes.filter(c=>!hit.matched.includes(c))];$('#snaponMatches').innerHTML='';$('#snaponSelected').hidden=false;$('#snaponSelected').innerHTML=`<div class="snapon-picked"><span class="dialog-category">PART FAMILY SELECTED</span><h3>${esc(selected.name)}</h3><p>${selected.codes.length} base number${selected.codes.length===1?'':'s'} kept together.</p>${selected.broad?'<p class="micro">This is a broad source group. Select the exact base for the component before continuing.</p>':''}<label class="note-label" for="snaponBase">Start with this base</label><select id="snaponBase" class="wide-select">${ordered.map(c=>`<option value="${c}">${c}${selected.bases.find(b=>b.number===c)?.label?' · '+esc(selected.bases.find(b=>b.number===c).label):''}</option>`).join('')}</select><button type="button" class="text-button" id="snaponChange">Choose another part</button></div>`;$('#snaponChange').onclick=showMatches;$('#snaponStatus').textContent='The catalog will use your VIN and selected base. Review position and application before saving a service number.';$('#snaponLaunch').disabled=false;$('#snaponLaunch').textContent=typeof window.PartsNative?.openEpc==='function'?'Find in integrated Snap-on ↗':'Continue to EPC lookup ↗';};
  $('#snaponForm').onsubmit=e=>{e.preventDefault();if(nativeLaunch.active()){toast('Finish the open catalog lookup first.');return;}try{const a=vinEntry.requireFull();if(!selected)throw Error('Choose a part family first.');const base=$('#snaponBase').value;if(!selected.codes.includes(base))throw Error('Choose a base from this family.');const book=api.getJobs();let job=api.getJob();if(job.vin!==a.vin){job=book.items.find(j=>j.vin===a.vin&&j.status!=='Done')||{...freshJob(),vin:a.vin,job:'Parts lookup · '+a.vin.slice(-6)};}const next=structuredClone(job);const existing=next.rows.find(r=>r.id===selected.id);if(existing)existing.bases=[...new Set([...existing.bases,...selected.codes])];else next.rows.push({id:selected.id,name:selected.name,bases:selected.codes,qty:1,note:''});if(!api.writeJobs({activeId:next.id,items:book.items.some(j=>j.id===next.id)?book.items.map(j=>j.id===next.id?next:j):[next,...book.items]}))return;if(typeof window.PartsNative?.openEpc==='function'){if(launchNative(next,selected.id,base,selected.name,selected.codes))toast('Opening integrated catalog');}else{openLookup(selected.id);$('#lookupBase').value=base;}}catch(error){$('#snaponStatus').textContent=error.message;}};
 }
 function launchNative(job,rowId,base,partName,bases){
  if(!analyzeVin(job?.vin).valid||!Array.isArray(bases)||!bases.length||!bases.every(b=>typeof b==='string'&&/^\d[A-Z0-9]{3,7}$/.test(b))||!bases.includes(base)){toast('Choose a valid vehicle and a base from this part family first.');return false;}
  const id='epc-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);
  if(!nativeLaunch.begin(id)){toast('Finish the open catalog lookup first.');return false;}
  if(!save('epc-pending',{id,jobId:job.id,rowId,vin:job.vin,base})){nativeLaunch.finish(id);return false;}
  try{window.PartsNative.openEpc(JSON.stringify({vin:job.vin,partName:String(partName||'Service part lookup').slice(0,160),bases:[base,...bases.filter(b=>b!==base)].slice(0,100),requestId:id}));return true;}
  catch(error){nativeLaunch.finish(id);save('epc-pending',null);toast('The catalog could not open. Try again.');return false;}
 }
 window.addEventListener('parts-epc-closed',e=>nativeLaunch.finish(e.detail?.requestId));

 function addPart(id,quiet=false){const p=api.getIndex().parts.find(p=>p.id===id);if(!p)return;const j=structuredClone(api.getJob());const row=j.rows.find(r=>r.id===id);if(row){if(!quiet)row.qty=Math.min(999,row.qty+1);}else j.rows.push({id,name:p.name,bases:p.codes,qty:1,note:''});if(saveJob(j)&&!quiet)toast('Added to '+(j.job||'current job'));return j.rows.find(r=>r.id===id);}
 function openJobs(){const book=api.getJobs();panel(`<span class="dialog-category">JOB DESK</span><h2>Every vehicle. Its own workspace.</h2><p>Switch between counter calls without losing the VIN, notes or selected service numbers.</p><button class="primary" id="newJob">＋ New job</button><div class="job-list">${book.items.map(j=>`<button class="job-card ${book.activeId===j.id?'current':''}" data-switch-job="${esc(j.id)}"><span class="job-avatar">${j.status==='Done'?'✓':'↗'}</span><span><strong>${esc(j.job||'Untitled job')}</strong><small>${esc(j.vehicle||j.vin||'Vehicle not set')}</small><small>${j.rows.length} part families · ${j.rows.filter(r=>r.selection&&!r.selection.stale).length} selected service numbers</small></span><span class="job-status">${esc(j.status||'Open')}</span></button>`).join('')}</div>`);
  $('#newJob').onclick=()=>{const j=freshJob();if(api.writeJobs({activeId:j.id,items:[j,...book.items]}))openJob();};
  document.querySelectorAll('[data-switch-job]').forEach(b=>b.onclick=()=>{if(api.writeJobs({...book,activeId:b.dataset.switchJob}))openJob();});
 }
 function openJob(){const j=api.getJob();panel(`<span class="dialog-category">CURRENT JOB</span><h2>${esc(j.job||'Build the next lookup.')}</h2><div class="tools-actions"><button class="secondary" id="allJobs">All jobs (${api.getJobs().items.length})</button><button class="secondary" id="jobDecode">VIN Decoder</button><button class="secondary" id="finishJob">${j.status==='Done'?'Reopen job':'Mark done'}</button></div><div class="job-fields"><label>Job / RO<input id="jobName" maxlength="200" value="${esc(j.job)}" placeholder="RO, stock number or counter call"></label><label>VIN / vehicle note<input id="jobVin" maxlength="200" value="${esc(j.vin)}" placeholder="Full VIN or last 8 characters"></label></div><div id="jobVinChoices" aria-live="polite"></div>${j.vehicle?`<p class="vehicle-summary">${esc(j.vehicle)}</p>`:''}<p class="micro">Changing the VIN marks earlier service selections for rechecking.</p><div id="jobRows">${j.rows.map((r,i)=>`<section class="job-row"><div class="job-row-title"><strong>${esc(r.name)}</strong><button class="text-button" data-job-remove="${i}" aria-label="Remove ${esc(r.name)}">Remove</button></div><div class="job-bases">${r.bases.slice(0,10).map(esc).join(' · ')}${r.bases.length>10?' + more':''}</div>${r.selection?`<div class="selection ${r.selection.stale?'stale':''}"><span>${r.selection.stale?'VEHICLE CHANGED · RECHECK':'EMPLOYEE SELECTED'}</span><strong>${esc(r.selection.serviceNumber)}</strong><small>${esc(r.selection.context||r.selection.description||'')}</small><small>${esc(r.selection.source)} · ${esc((r.selection.selectedAt||'').slice(0,10))}</small></div>`:'<p class="pending-selection">Service number not selected</p>'}<div class="job-inputs"><label>Qty<input type="number" min="1" max="999" data-job-qty="${i}" value="${r.qty}"></label><label>Counter note<input data-job-note2="${i}" maxlength="1000" value="${esc(r.note)}" placeholder="Bin, position, reminder…"></label></div><div class="tools-actions"><button class="primary" data-job-epc="${esc(r.id)}">Find service part ↗</button>${r.selection?`<button class="secondary" data-copy-part="${esc(r.selection.serviceNumber)}" data-copy-row="${esc(r.id)}" ${r.selection.stale?'disabled title="Recheck this part for the current VIN first"':''}>Copy number</button>`:''}</div></section>`).join('')||'<div class="job-empty">Search for a part, then add it to this job.</div>'}</div><div class="tools-actions"><button class="primary" id="copyPartsList">Copy selected parts</button><button class="secondary" id="copyJob">Copy full job</button><button class="secondary" id="exportJob">Export CSV</button><button class="secondary" id="printJob">Print job</button></div>`);
  $('#allJobs').onclick=openJobs;$('#jobDecode').onclick=api.showVin;
  $('#finishJob').onclick=()=>{if(saveJob({...api.getJob(),status:j.status==='Done'?'Open':'Done'}))openJob();};
  $('#jobName').oninput=e=>saveJob({...api.getJob(),job:e.target.value});
  const vinEntry=createVinEntry({input:$('#jobVin'),choices:$('#jobVinChoices'),esc,getRecords:()=>[...savedVehicles(),j],onConfirmed:r=>{if(saveJob(changeVehicle(api.getJob(),r.vin)))openJob();}});
  $('#jobVin').oninput=e=>{vinEntry.render();if(saveJob(changeVehicle(api.getJob(),e.target.value.trim().toUpperCase()))){document.querySelectorAll('#jobRows .selection').forEach(s=>{s.classList.add('stale');s.querySelector('span').textContent='VEHICLE CHANGED · RECHECK';});document.querySelectorAll('[data-copy-part]').forEach(b=>b.disabled=true);}};
  $('#jobRows').oninput=e=>{const next=structuredClone(api.getJob());if(e.target.hasAttribute('data-job-qty')){const q=Number(e.target.value);if(!Number.isInteger(q)||q<1||q>999)return;next.rows[+e.target.dataset.jobQty].qty=q;}else if(e.target.hasAttribute('data-job-note2'))next.rows[+e.target.dataset.jobNote2].note=e.target.value;else return;saveJob(next);};
  $('#jobRows').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.jobEpc)openLookup(b.dataset.jobEpc);if(b.dataset.copyPart){const job=api.getJob(),row=job.rows.find(r=>r.id===b.dataset.copyRow);if(row&&selectedPartsList({...job,rows:[row]}).count)copy(row.selection.serviceNumber);else toast('Recheck this part for the current VIN before copying.');}if(b.hasAttribute('data-job-remove')){const next=structuredClone(api.getJob());next.rows.splice(+b.dataset.jobRemove,1);if(saveJob(next))openJob();}};
  const summary=()=>{const j=api.getJob();return [j.job,j.vehicle||'',j.vin,...j.rows.map(r=>`${r.qty} × ${r.name}\n${r.selection?(r.selection.stale?'RECHECK: ':'Selected: ')+r.selection.serviceNumber:'Base candidates: '+r.bases.join(', ')}${r.selection?.context?'\n'+r.selection.context:''}${r.note?'\n'+r.note:''}`),'Selections are employee-reviewed references. Check current EPC restrictions and supersessions.'].filter(Boolean).join('\n\n');};
  $('#copyPartsList').onclick=()=>{const list=selectedPartsList(api.getJob());if(!list.count){toast('Select and review service parts for this VIN first.');return;}copy(list.text);if(list.omitted)toast('Copied '+list.count+' selected numbers. '+list.omitted+' unselected or stale job items were left out.');};
  $('#copyJob').onclick=()=>copy(summary());$('#exportJob').onclick=()=>{const j=api.getJob(),cell=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('Ford-Parts-Desk-job.csv',['job,vin,quantity,part,bases,service_number,selection_status,note',...j.rows.map(r=>[j.job,j.vin,r.qty,r.name,r.bases.join(';'),r.selection?.serviceNumber||'',r.selection?(r.selection.stale?'recheck':'employee selected'):'not selected',r.note].map(cell).join(','))].join('\r\n'));};
  $('#printJob').onclick=()=>{if(typeof window.PartsNative?.printJob==='function')window.PartsNative.printJob(summary());else{let area=document.querySelector('#printArea');if(!area){area=document.createElement('pre');area.id='printArea';document.body.append(area);}area.textContent=summary();window.print();}};
 }
 function openLookup(rowId){const row=api.getJob().rows.find(r=>r.id===rowId)||addPart(rowId,true);if(!row)return;const j=api.getJob();lookup={jobId:j.id,rowId};const bases=row.bases.map(number=>({number,label:api.getIndex().byBase.get(number)?.bases.find(b=>b.number===number)?.label||''}));
  panel(`<span class="dialog-category">VIN → SERVICE PART</span><h2>${esc(row.name)}</h2><div class="lookup-steps"><span>01 · Choose base</span><span>02 · Open EPC</span><span>03 · Save selection</span></div><label class="note-label" for="lookupVin">VIN</label><div class="detail-filter"><input id="lookupVin" maxlength="30" value="${esc(j.vin)}" placeholder="Full VIN or last 8 characters" autocapitalize="characters"></div><div id="lookupVinChoices" aria-live="polite"></div><label class="note-label" for="lookupBase">Base number</label><select class="wide-select" id="lookupBase">${bases.map(b=>`<option value="${b.number}">${b.number}${b.label?' · '+esc(b.label):''}</option>`).join('')}</select><p id="lookupStatus" role="status">The VIN and base identify candidates. Choose the correct position and application in EPC.</p><button class="primary wide" id="launchEpc">${typeof window.PartsNative?.openEpc==='function'?'Open guided parts lookup ↗':'Open Snap-on EPC ↗'}</button><p class="micro">${typeof window.PartsNative?.openEpc==='function'?'Your VIN and base load automatically after sign-in. Choose the location and application from the app menus; Find parts retries the lookup. Sign in through Catalog / sign in when needed. Your desktop login does not transfer to the phone.':'In this browser version, open your signed-in EPC tab, enter the VIN and base, then record your selected number below. Android includes guided catalog menus and service-part cards.'}</p><div class="tools-actions"><button class="secondary" id="copyLookupVin">Copy VIN</button><button class="secondary" id="copyLookupBase">Copy base</button></div><details class="manual-selection"><summary>Record a number reviewed in EPC</summary><form id="manualPart"><label class="note-label">Full service number<input id="serviceNumber" required maxlength="40" placeholder="Full number from EPC"></label><label class="note-label">Position / application<input id="serviceContext" required maxlength="500" placeholder="Front, rear, equipment or restrictions"></label><label class="confirm-line"><input type="checkbox" required> I checked this number against the VIN and application in EPC.</label><button class="primary" type="submit">Save to job</button></form></details>`);
  const vinEntry=createVinEntry({input:$('#lookupVin'),choices:$('#lookupVinChoices'),esc,getRecords:savedVehicles});
  const getRequest=()=>{const a=vinEntry.requireFull();const book=api.getJobs(),job=book.items.find(x=>x.id===lookup.jobId);if(!job)throw Error('This job no longer exists.');if(job.vin!==a.vin&&!saveJob(changeVehicle(job,a.vin)))throw Error('Could not save the VIN.');const base=$('#lookupBase').value;if(!row.bases.includes(base)||!/^\d[A-Z0-9]{3,7}$/.test(base))throw Error('Choose a valid base from this part family.');return {vin:a.vin,base};};
  $('#copyLookupVin').onclick=()=>copy($('#lookupVin').value.trim().toUpperCase());$('#copyLookupBase').onclick=()=>copy($('#lookupBase').value);
  $('#launchEpc').onclick=()=>{if(nativeLaunch.active()){toast('Finish the open catalog lookup first.');return;}try{const r=getRequest();if(typeof window.PartsNative?.openEpc==='function'){launchNative(api.getJobs().items.find(j=>j.id===lookup.jobId),lookup.rowId,r.base,row.name,row.bases);}else window.open('https://snaponepc.com/epc/','_blank','noopener');}catch(e){$('#lookupStatus').textContent=e.message;}};
  $('#manualPart').onsubmit=e=>{e.preventDefault();try{const r=getRequest(),next=attachSelection(api.getJob(),rowId,{...r,serviceNumber:$('#serviceNumber').value.trim().toUpperCase(),context:$('#serviceContext').value.trim(),source:'Manual EPC review — employee entered'});if(saveJob(next)){toast('Service number saved to job');openJob();}}catch(e){$('#lookupStatus').textContent=e.message;}};
 }
 function receiveEpc(){if(typeof window.PartsNative?.getEpcResult!=='function')return;const raw=window.PartsNative.getEpcResult();if(!raw)return;try{const r=JSON.parse(raw),pending=read('epc-pending',null);if(!pending||r.requestId!==pending.id)throw Error('This EPC result belongs to an earlier lookup. Start a new lookup.');const book=api.getJobs(),job=book.items.find(j=>j.id===pending.jobId);if(!job)throw Error('The lookup job could not be found.');const next=attachSelection(job,pending.rowId,r);if(!api.writeJobs({activeId:job.id,items:book.items.map(j=>j.id===job.id?next:j)}))return;window.PartsNative.acknowledgeEpcResult();nativeLaunch.finish(r.requestId);save('epc-pending',null);toast('EPC selection saved');openJob();}catch(e){toast(e.message);window.PartsNative.acknowledgeEpcResult();}}
 window.addEventListener('parts-epc-result',receiveEpc);
 function receiveVinResolution(){const pending=readPendingVinResolution();if(pending)toast('Your confirmed VIN ending '+pending.suffix+' is saved. Enter those last 8 to review it.');}
 return {openJobs,openJob,openSnapOn,addPart,openLookup,receiveEpc,receiveVinResolution};
}

